import pako from "pako";
import { DetectionOptions, DetectionResult } from "../../detection/detection-interface.js";
import { BaseBinaryDetector, DetectionUtils } from "../../detection/unified-detector.js";
import { ProgressOptions, ProgressTracker } from "../../progress/index.js";
import { TarHandler } from "../archive/tar-handler.js";

export interface GzipDecompressionResult {
  success: boolean;
  data?: string;
  binaryData?: Uint8Array; // Add binary data for tar archives
  error?: string;
  originalSize: number;
  decompressedSize: number;
  processingTime: number;
  progress?: {
    percentage: number;
    bytesProcessed: number;
    totalBytes: number;
    stage: string;
  };
}

/**
 * Handles gzip decompression of downloaded data
 */
export class GzipHandler extends BaseBinaryDetector {
  private tarHandler: TarHandler;

  constructor() {
    super();
    this.tarHandler = new TarHandler();
  }

  // FormatDetector interface implementation
  getFormatName(): string {
    return "gzip";
  }

  getMimeType(): string {
    return "application/gzip";
  }

  getFileExtensions(): string[] {
    return [".gz", ".gzip"];
  }

  analyzeBinary(data: Uint8Array): DetectionResult {
    const indicators = {
      hasMagicBytes: this.checkGzipMagicBytes(data),
      hasMinimumSize: data.length > 2,
      hasValidHeader: this.checkGzipHeader(data)
    };

    const weights = {
      hasMagicBytes: 3,
      hasMinimumSize: 1,
      hasValidHeader: 2
    };

    const confidence = DetectionUtils.calculateConfidence(indicators, weights);
    const isDetected = indicators.hasMagicBytes && indicators.hasMinimumSize;

    return {
      isDetected,
      confidence,
      indicators,
      metadata: DetectionUtils.extractMetadata(indicators)
    };
  }

  /**
   * Check if data appears to be gzip compressed (legacy method)
   */
  isGzipCompressed(data: Uint8Array): boolean {
    return this.checkGzipMagicBytes(data);
  }

  /**
   * Check for gzip magic bytes
   */
  private checkGzipMagicBytes(data: Uint8Array): boolean {
    return data.length > 2 && data[0] === 0x1f && data[1] === 0x8b;
  }

  /**
   * Check for valid gzip header structure
   */
  private checkGzipHeader(data: Uint8Array): boolean {
    if (data.length < 10) return false;
    
    // Check magic bytes
    if (!this.checkGzipMagicBytes(data)) return false;
    
    // Check compression method (should be 8 for deflate)
    if (data[2] !== 8) return false;
    
    // Check flags (should be valid)
    const flags = data[3];
    if (flags & 0xe0) return false; // Reserved bits should be 0
    
    return true;
  }

  /**
   * Decompress with timeout protection to prevent hanging
   * This is critical for preventing the hanging issue reported by users
   */
  private async decompressWithTimeout(data: Uint8Array, timeoutMs: number): Promise<Uint8Array> {
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        const timeoutError = new Error(`Decompression timeout after ${timeoutMs}ms for ${data.length} bytes`);
        reject(timeoutError);
      }, timeoutMs);

      try {
        // Use pako for reliable decompression
        const decompressed = pako.inflate(data);
        clearTimeout(timeoutId);
        resolve(decompressed);
      } catch (error) {
        clearTimeout(timeoutId);
        reject(error);
      }
    });
  }

  /**
   * Yield control to the UI thread to prevent blocking
   * This is used after decompression to prevent UI freezing
   */
  private async yieldToUI(): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, 0));
  }

  /**
   * Decompress gzip data with detailed logging and error handling
   */
  async decompress(data: Uint8Array, progressOptions?: ProgressOptions): Promise<GzipDecompressionResult> {
    const startTime = Date.now();
    const originalSize = data.length;

    // Initialize progress tracking
    const progressTracker = new ProgressTracker(progressOptions);
    progressTracker.initialize(originalSize, 'decompressing');

    // Add overall timeout protection (60 seconds max)
    const overallTimeout = setTimeout(() => {
      const timeoutError = new Error(`Gzip decompression timeout after 60 seconds for ${originalSize} bytes`);
      progressTracker.errorAtStage(timeoutError, 'decompressing', 'TIMEOUT');
      throw timeoutError;
    }, 60000);

    try {
      // Use pako for gzip decompression
      let workingView = data;

      if (data[data.length - 1] === 0x3b) {
        workingView = data.slice(0, -1);
      }

      // CRITICAL FIX: Use ONLY pako for all decompression to avoid browser DecompressionStream hanging issues
      // Native DecompressionStream has known issues with large files that cause indefinite hanging
      // This is the root cause of the timeout issues reported by users
      let decompressed: Uint8Array;
      
      // Update progress - starting decompression
      progressTracker.updateProgress(0, 'decompressing');
      
      // ALWAYS use pako - never use native DecompressionStream
      // This fixes the hanging issue completely
      try {
        // Use configurable timeout wrapper for pako decompression to prevent hanging
        const timeoutMs = progressOptions?.decompressionTimeout || 30000; // Default 30 seconds
        decompressed = await this.decompressWithTimeout(workingView, timeoutMs);
        // Update progress - decompression complete
        progressTracker.updateProgress(workingView.length, 'decompressing');
      } catch (pakoError) {
        // If pako fails, report the error with progress context
        const error = new Error(`Pako decompression failed: ${pakoError instanceof Error ? pakoError.message : String(pakoError)}`);
        progressTracker.errorAtStage(error, 'decompressing', 'PAKO_ERROR');
        throw error;
      }

      const xmlText = new TextDecoder().decode(decompressed);


      // Check if this is a tar archive after gzip decompression using unified detection
      const isTarArchive = this.tarHandler.isTarArchive(xmlText);

      if (isTarArchive) {
        // Return binary data for tar extraction to avoid corruption
        return {
          success: true,
          data: xmlText,
          binaryData: decompressed,
          originalSize,
          decompressedSize: xmlText.length,
          processingTime: Date.now() - startTime
        };
      }

      // Yield to UI thread after decompression to prevent freezing
      await new Promise((resolve) => setTimeout(resolve, 1));

      const endTime = Date.now();
      const processingTime = endTime - startTime;

      // Clear timeout on success
      clearTimeout(overallTimeout);

      // Complete progress tracking
      progressTracker.complete();

      return {
        success: true,
        data: xmlText,
        originalSize,
        decompressedSize: xmlText.length,
        processingTime,
        progress: {
          percentage: 100,
          bytesProcessed: originalSize,
          totalBytes: originalSize,
          stage: 'completed'
        }
      };

    } catch (err) {
      const endTime = Date.now();
      const processingTime = endTime - startTime;

      // Clear timeout on error
      clearTimeout(overallTimeout);

      // Report error with progress context
      const error = err instanceof Error ? err : new Error(String(err));
      progressTracker.errorAtStage(error, 'decompressing', 'DECOMPRESSION_ERROR');

      return {
        success: false,
        error: error.message,
        originalSize,
        decompressedSize: 0,
        processingTime,
        progress: {
          percentage: Math.min(100, (progressTracker.getStats().totalBytesProcessed / originalSize) * 100),
          bytesProcessed: progressTracker.getStats().totalBytesProcessed,
          totalBytes: originalSize,
          stage: 'error'
        }
      };
    }
  }
}
