import { ConfigurationManager } from '../configuration/configuration.js';
import {
  HandlerRegistry,
  CompressionResult,
  ArchiveExtractionResult,
} from '../configuration/handler-registry.js';
import {
  FormatProcessingResult,
  FormatProcessingOptions,
} from './format-processing-types.js';

/**
 * Extensible format processor that uses the handler registry
 */
export class FormatProcessor {
  private registry: HandlerRegistry;
  private configManager: ConfigurationManager;

  constructor(registry: HandlerRegistry, configManager: ConfigurationManager) {
    this.registry = registry;
    this.configManager = configManager;
  }

  /**
   * Process downloaded data through the complete format detection and extraction pipeline
   */
  async processData(
    data: ArrayBuffer,
    options: FormatProcessingOptions
  ): Promise<FormatProcessingResult> {
    const startTime = Date.now();
    const originalSize = data.byteLength;
    const processingSteps: string[] = [];
    let extractedXmlFiles: Array<{ name: string; size: number }> | undefined;

    // Check file size limit
    const maxFileSize = this.configManager.getProcessingConfig().maxFileSize;
    if (maxFileSize && originalSize > maxFileSize) {
      return {
        success: false,
        error: `File size ${originalSize} exceeds maximum allowed size ${maxFileSize}`,
        contentType: 'unknown',
        confidence: 'low',
        processingSteps: ['File size validation'],
        totalProcessingTime: Date.now() - startTime,
        originalSize,
        finalSize: 0,
      };
    }

    try {
      const view = new Uint8Array(data);
      let xmlText: string = '';
      let contentType: string = 'unknown';
      let confidence: 'high' | 'medium' | 'low' = 'low';

      // Step 1: Try compression handlers
      const compressionHandlers = this.registry.getEnabledCompressionHandlers();
      let decompressionResult: CompressionResult | null = null;

      for (const handler of compressionHandlers) {
        if (handler.isCompressed(view)) {
          processingSteps.push(`${handler.getFormatName()} decompression`);

          try {
            decompressionResult = await handler.decompress(view, options.progressOptions);
            if (decompressionResult.success) {
              xmlText = decompressionResult.data!;
              processingSteps.push(
                `${handler.getFormatName()} decompression completed (${
                  decompressionResult.decompressedSize
                } chars)`
              );
              break;
            } else {
              processingSteps.push(
                `${handler.getFormatName()} decompression failed: ${
                  decompressionResult.error
                }`
              );
            }
          } catch (error) {
            processingSteps.push(
              `${handler.getFormatName()} decompression error: ${
                error instanceof Error ? error.message : String(error)
              }`
            );
          }
        }
      }

      // If no compression was detected or successful, treat as uncompressed
      if (!decompressionResult || !decompressionResult.success) {
        processingSteps.push('No compression detected');
        xmlText = new TextDecoder().decode(data);
        processingSteps.push(
          `Text decoding completed (${xmlText.length} chars)`
        );
      }

      // Step 2: Content type detection
      processingSteps.push('Content type detection');
      const contentTypeHandlers = this.registry.getEnabledContentTypeHandlers();

      for (const handler of contentTypeHandlers) {
        try {
          const analysis = handler.detectContentType(
            xmlText,
            options.projectId
          );
          if (
            analysis.confidence === 'high' ||
            (analysis.confidence === 'medium' && confidence === 'low')
          ) {
            contentType = analysis.type;
            confidence = analysis.confidence;
            processingSteps.push(
              `Content type detected as ${contentType} (${confidence} confidence)`
            );
            break;
          }
        } catch (error) {
          processingSteps.push(
            `Content type detection error: ${
              error instanceof Error ? error.message : String(error)
            }`
          );
        }
      }

      // Step 3: Handle archives if detected
      if (
        contentType === 'tar' &&
        this.configManager.getProcessingConfig().enableTarExtraction !== false
      ) {
        processingSteps.push('Archive extraction');

        const archiveHandlers = this.registry.getEnabledArchiveHandlers();
        let extractionResult: ArchiveExtractionResult | null = null;

        for (const handler of archiveHandlers) {
          if (handler.isArchive(xmlText)) {
            try {
              // Use binary data if available from decompression
              const dataToExtract = decompressionResult?.binaryData
                ? decompressionResult.binaryData.buffer
                : data;

              extractionResult = await handler.extractArchive(dataToExtract);

              if (extractionResult.success) {
                xmlText = extractionResult.xmlContent!;
                contentType = 'xml';
                confidence = 'high';
                processingSteps.push(
                  `Archive extraction completed (${extractionResult.extractedFiles.length} files)`
                );

                // Store information about all extracted XML files
                extractedXmlFiles = extractionResult.xmlFiles.map((f) => ({
                  name: f.name,
                  size: f.size,
                }));
                break;
              } else {
                processingSteps.push(
                  `Archive extraction failed: ${extractionResult.error}`
                );
              }
            } catch (error) {
              processingSteps.push(
                `Archive extraction error: ${
                  error instanceof Error ? error.message : String(error)
                }`
              );
            }
          }
        }

        if (!extractionResult || !extractionResult.success) {
          throw new Error(
            'Archive extraction failed or no suitable handler found'
          );
        }
      }

      // Step 4: Final validation
      processingSteps.push('Final content validation');

      // Check for empty content
      if (xmlText.length === 0) {
        throw new Error(
          'Decompressed content is empty - file may be corrupted or download failed'
        );
      }

      // Content type-specific validation
      if (contentType === 'xml') {
        // Check for basic XML structure
        if (!xmlText.includes('<?xml') && !xmlText.includes('<')) {
          throw new Error(
            'Decompressed content does not appear to be valid XML - file may be corrupted'
          );
        }
        processingSteps.push('XML validation passed');
      } else if (contentType === 'tsv') {
        // For TSV content, validate tab separators and structure
        if (!xmlText.includes('\t')) {
          throw new Error(
            'TSV content does not contain tab separators - file may be corrupted'
          );
        }
        processingSteps.push('TSV validation passed');
      } else if (contentType === 'tar') {
        // For tar content, basic validation that it's not empty
        processingSteps.push('Tar validation passed');
      } else {
        // For unknown content types, proceed without specific validation
        processingSteps.push('Unknown content type - no validation');
      }

      const endTime = Date.now();
      const totalProcessingTime = endTime - startTime;

      return {
        success: true,
        xmlContent: xmlText,
        contentType: contentType as any,
        confidence,
        processingSteps,
        totalProcessingTime,
        originalSize,
        finalSize: xmlText.length,
        extractedXmlFiles,
      };
    } catch (error) {
      const endTime = Date.now();
      const totalProcessingTime = endTime - startTime;

      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
        contentType: 'unknown',
        confidence: 'low',
        processingSteps,
        totalProcessingTime,
        originalSize,
        finalSize: 0,
      };
    }
  }

  /**
   * Get processing statistics for debugging
   */
  getProcessingStats(): {
    handlers: {
      compression: number;
      contentType: number;
      archive: number;
      detector: number;
    };
    config: any;
  } {
    const stats = this.registry.getStats();
    return {
      handlers: {
        compression: stats.byType.compression || 0,
        contentType: stats.byType.contentType || 0,
        archive: stats.byType.archive || 0,
        detector: stats.byType.detector || 0,
      },
      config: this.configManager.getConfig(),
    };
  }

  /**
   * Get available handlers
   */
  getAvailableHandlers(): {
    compression: string[];
    contentType: string[];
    archive: string[];
    detector: string[];
  } {
    const allHandlers = this.registry.getAllHandlers();

    return {
      compression: allHandlers
        .filter((h) => h.type === 'compression' && h.enabled)
        .map((h) => h.name),
      contentType: allHandlers
        .filter((h) => h.type === 'contentType' && h.enabled)
        .map((h) => h.name),
      archive: allHandlers
        .filter((h) => h.type === 'archive' && h.enabled)
        .map((h) => h.name),
      detector: allHandlers
        .filter((h) => h.type === 'detector' && h.enabled)
        .map((h) => h.name),
    };
  }
}
