import { ArchiveHandler, ArchiveExtractionResult, ExtractedFile } from "../configuration/handler-registry.js";
import { TarHandler as OriginalTarHandler, TarExtractionResult, ExtractedFile as OriginalExtractedFile } from "../handlers/archive/tar-handler.js";

/**
 * Adapter for TarHandler to implement ArchiveHandler interface
 */
export class TarArchiveAdapter implements ArchiveHandler {
  private handler: OriginalTarHandler;

  constructor() {
    this.handler = new OriginalTarHandler();
  }

  isArchive(content: string): boolean {
    return this.handler.isTarArchive(content);
  }

  async extractArchive(data: ArrayBuffer): Promise<ArchiveExtractionResult> {
    const result = await this.handler.extractTarArchive(data);
    
    // Convert ExtractedFile format
    const xmlFiles: ExtractedFile[] = result.xmlFiles.map((file: OriginalExtractedFile) => ({
      name: file.name,
      content: file.content,
      size: file.size
    }));
    
    return {
      success: result.success,
      xmlContent: result.xmlContent,
      error: result.error,
      extractedFiles: result.extractedFiles,
      xmlFile: result.xmlFile,
      xmlFiles,
      processingTime: result.processingTime
    };
  }

  getFormatName(): string {
    return this.handler.getFormatName();
  }

  getMimeType(): string {
    return this.handler.getMimeType();
  }

  getFileExtensions(): string[] {
    return this.handler.getFileExtensions();
  }
}
