import { 
  DetectionResult, 
  DetectionOptions, 
  FormatDetector, 
  TextFormatDetector, 
  BinaryFormatDetector, 
  CompositeDetector 
} from "./detection-interface.js";

/**
 * Unified detection system that coordinates all format detectors
 */
export class UnifiedDetector implements CompositeDetector {
  private detectors: Map<string, FormatDetector> = new Map();

  /**
   * Register a detector for a specific format
   */
  registerDetector<T extends FormatDetector>(detector: T): void {
    this.detectors.set(detector.getFormatName(), detector);
  }

  /**
   * Detect the format of the given data
   */
  detectFormat(data: Uint8Array | string, options?: DetectionOptions): {
    format: string;
    result: DetectionResult;
    detector: FormatDetector;
  } | null {
    const results: Array<{
      format: string;
      result: DetectionResult;
      detector: FormatDetector;
      score: number;
    }> = [];

    // Try all registered detectors
    for (const [formatName, detector] of this.detectors) {
      try {
        const result = detector.detect(data as any, options);
        
        // Calculate confidence score (high=3, medium=2, low=1)
        const score = result.confidence === "high" ? 3 : 
                     result.confidence === "medium" ? 2 : 1;
        
        results.push({
          format: formatName,
          result,
          detector,
          score
        });
      } catch (error) {
        // Skip detectors that fail
        console.warn(`Detector ${formatName} failed:`, error);
      }
    }

    // Sort by confidence score (highest first)
    results.sort((a, b) => b.score - a.score);

    // Return the best match if any detector found something
    const bestMatch = results.find(r => r.result.isDetected);
    if (bestMatch) {
      return {
        format: bestMatch.format,
        result: bestMatch.result,
        detector: bestMatch.detector
      };
    }

    return null;
  }

  /**
   * Get all registered detectors
   */
  getDetectors(): FormatDetector[] {
    return Array.from(this.detectors.values());
  }

  /**
   * Get detector for a specific format
   */
  getDetector(formatName: string): FormatDetector | null {
    return this.detectors.get(formatName) || null;
  }
}

/**
 * Base implementation for binary format detectors
 */
export abstract class BaseBinaryDetector implements BinaryFormatDetector {
  abstract getFormatName(): string;
  abstract getMimeType(): string;
  abstract getFileExtensions(): string[];
  abstract analyzeBinary(data: Uint8Array, options?: DetectionOptions): DetectionResult;

  detect(data: Uint8Array, options?: DetectionOptions): DetectionResult {
    return this.analyzeBinary(data, options);
  }
}

/**
 * Base implementation for text format detectors
 */
export abstract class BaseTextDetector implements TextFormatDetector {
  abstract getFormatName(): string;
  abstract getMimeType(): string;
  abstract getFileExtensions(): string[];
  abstract analyzeText(content: string, options?: DetectionOptions): DetectionResult;

  detect(data: string, options?: DetectionOptions): DetectionResult {
    return this.analyzeText(data, options);
  }
}

/**
 * Utility functions for common detection patterns
 */
export class DetectionUtils {
  /**
   * Check for magic bytes at the beginning of data
   */
  static checkMagicBytes(data: Uint8Array, magicBytes: number[]): boolean {
    if (data.length < magicBytes.length) return false;
    
    for (let i = 0; i < magicBytes.length; i++) {
      if (data[i] !== magicBytes[i]) return false;
    }
    
    return true;
  }

  /**
   * Check for text patterns in data
   */
  static checkTextPatterns(text: string, patterns: RegExp[]): boolean {
    return patterns.some(pattern => pattern.test(text));
  }

  /**
   * Calculate confidence based on multiple indicators
   */
  static calculateConfidence(indicators: Record<string, boolean>, weights: Record<string, number>): "high" | "medium" | "low" {
    let totalWeight = 0;
    let matchedWeight = 0;

    for (const [indicator, isPresent] of Object.entries(indicators)) {
      const weight = weights[indicator] || 1;
      totalWeight += weight;
      if (isPresent) {
        matchedWeight += weight;
      }
    }

    if (totalWeight === 0) return "low";

    const ratio = matchedWeight / totalWeight;
    
    if (ratio >= 0.8) return "high";
    if (ratio >= 0.5) return "medium";
    return "low";
  }

  /**
   * Extract metadata from detection indicators
   */
  static extractMetadata(indicators: Record<string, boolean>): Record<string, any> {
    const metadata: Record<string, any> = {};
    
    // Extract specific indicators as metadata
    if (indicators.hasMagicBytes) metadata.magicBytes = true;
    if (indicators.hasTextPatterns) metadata.textPatterns = true;
    if (indicators.hasBinaryContent) metadata.binaryContent = true;
    if (indicators.hasNullBytes) metadata.nullBytes = true;
    
    return metadata;
  }
}
