import { 
  ProgressInfo, 
  ProcessingStage, 
  ProgressOptions, 
  ProcessingStats 
} from './types.js';

export class ProgressTracker {
  private stats: ProcessingStats;
  private options: Required<ProgressOptions>;
  private lastProgressTime: number = 0;
  private lastProgressBytes: number = 0;

  constructor(options: ProgressOptions = {}) {
    this.options = {
      onProgress: options.onProgress || (() => {}),
      dataInterval: options.dataInterval || 1024 * 1024, // 1MB default
      timeInterval: options.timeInterval || 1000, // 1 second default
      minUpdateInterval: options.minUpdateInterval || 100, // 100ms minimum
      detailed: options.detailed || false,
      decompressionTimeout: options.decompressionTimeout || 30000 // 30 seconds default
    };

    this.stats = {
      startTime: Date.now(),
      currentStage: 'initializing',
      totalBytesProcessed: 0,
      totalBytes: 0,
      lastUpdateTime: Date.now(),
      updateCount: 0,
      completedStages: []
    };
  }

  /**
   * Initialize progress tracking with total bytes
   */
  initialize(totalBytes: number, stage: ProcessingStage = 'initializing'): void {
    this.stats.totalBytes = totalBytes;
    this.stats.currentStage = stage;
    this.stats.startTime = Date.now();
    this.stats.totalBytesProcessed = 0;
    this.stats.updateCount = 0;
    this.stats.completedStages = [];
    this.lastProgressTime = 0;
    this.lastProgressBytes = 0;
  }

  /**
   * Update progress with bytes processed
   */
  updateProgress(bytesProcessed: number, stage?: ProcessingStage): void {
    const now = Date.now();
    const timeSinceLastUpdate = now - this.lastProgressTime;
    const bytesSinceLastUpdate = bytesProcessed - this.lastProgressBytes;

    // Update stats
    this.stats.totalBytesProcessed = bytesProcessed;
    this.stats.currentStage = stage || this.stats.currentStage;
    this.stats.lastUpdateTime = now;

    // Check if we should send a progress update
    const shouldUpdateByData = bytesSinceLastUpdate >= this.options.dataInterval;
    const shouldUpdateByTime = timeSinceLastUpdate >= this.options.timeInterval;
    const shouldUpdateByMinInterval = timeSinceLastUpdate >= this.options.minUpdateInterval;

    if ((shouldUpdateByData || shouldUpdateByTime) && shouldUpdateByMinInterval) {
      this.sendProgressUpdate();
      this.lastProgressTime = now;
      this.lastProgressBytes = bytesProcessed;
    }
  }

  /**
   * Update processing stage
   */
  updateStage(stage: ProcessingStage): void {
    if (this.stats.currentStage !== stage) {
      this.stats.completedStages.push(this.stats.currentStage);
      this.stats.currentStage = stage;
      this.sendProgressUpdate();
    }
  }

  /**
   * Complete processing
   */
  complete(): void {
    this.stats.completedStages.push(this.stats.currentStage);
    this.stats.currentStage = 'completed';
    this.stats.totalBytesProcessed = this.stats.totalBytes;
    this.sendProgressUpdate();
  }

  /**
   * Report error with detailed information
   */
  error(error: Error, code?: string): void {
    this.stats.error = error;
    this.stats.currentStage = 'error';
    
    // Send immediate error progress update
    this.sendErrorProgressUpdate(error, code);
  }

  /**
   * Report error at specific stage with progress context
   */
  errorAtStage(error: Error, stage: ProcessingStage, code?: string): void {
    this.stats.error = error;
    this.stats.currentStage = 'error';
    
    // Send immediate error progress update with stage context
    this.sendErrorProgressUpdate(error, code, stage);
  }

  /**
   * Get current processing stats
   */
  getStats(): ProcessingStats {
    return { ...this.stats };
  }

  /**
   * Send progress update to callback
   */
  private sendProgressUpdate(): void {
    const progress: ProgressInfo = {
      percentage: Math.min(100, (this.stats.totalBytesProcessed / this.stats.totalBytes) * 100),
      bytesProcessed: this.stats.totalBytesProcessed,
      totalBytes: this.stats.totalBytes,
      elapsedTime: Date.now() - this.stats.startTime,
      estimatedTimeRemaining: this.calculateEstimatedTimeRemaining(),
      stage: this.stats.currentStage,
      metadata: this.options.detailed ? {
        updateCount: this.stats.updateCount,
        completedStages: this.stats.completedStages,
        currentStage: this.stats.currentStage,
        error: this.stats.error?.message
      } : undefined
    };

    this.stats.updateCount++;
    
    try {
      this.options.onProgress(progress);
    } catch (error) {
      console.warn('Progress callback error:', error);
    }
  }

  /**
   * Send error progress update to callback
   */
  private sendErrorProgressUpdate(error: Error, code?: string, stage?: ProcessingStage): void {
    const progress: ProgressInfo = {
      percentage: Math.min(100, (this.stats.totalBytesProcessed / this.stats.totalBytes) * 100),
      bytesProcessed: this.stats.totalBytesProcessed,
      totalBytes: this.stats.totalBytes,
      elapsedTime: Date.now() - this.stats.startTime,
      estimatedTimeRemaining: 0, // No time remaining on error
      stage: 'error',
      error: {
        message: error.message,
        code: code || 'UNKNOWN_ERROR',
        stage: stage || this.stats.currentStage,
        bytesProcessed: this.stats.totalBytesProcessed,
        timestamp: Date.now()
      },
      metadata: this.options.detailed ? {
        updateCount: this.stats.updateCount,
        completedStages: this.stats.completedStages,
        currentStage: this.stats.currentStage,
        errorStack: error.stack,
        errorName: error.name
      } : undefined
    };

    this.stats.updateCount++;
    
    try {
      this.options.onProgress(progress);
    } catch (callbackError) {
      console.warn('Progress callback error during error reporting:', callbackError);
    }
  }

  /**
   * Calculate estimated time remaining based on current progress
   */
  private calculateEstimatedTimeRemaining(): number | undefined {
    if (this.stats.totalBytesProcessed === 0 || this.stats.totalBytes === 0) {
      return undefined;
    }

    const elapsed = Date.now() - this.stats.startTime;
    const progressRatio = this.stats.totalBytesProcessed / this.stats.totalBytes;
    
    if (progressRatio === 0) {
      return undefined;
    }

    const estimatedTotalTime = elapsed / progressRatio;
    return Math.max(0, estimatedTotalTime - elapsed);
  }
}
