/**
 * Shared tar detection utilities to avoid code duplication
 */

export interface TarDetectionResult {
  isTarArchive: boolean;
  indicators: {
    hasUstar: boolean;
    hasPaxHeader: boolean;
    hasGlobalHeader: boolean;
    hasTarEntryPattern: boolean;
    hasUstarMagic: boolean;
    hasGnuTar: boolean;
    hasNullBytes: boolean;
  };
}

/**
 * Detects if content appears to be a tar archive
 * This is a shared utility to avoid code duplication between
 * ContentTypeDetector and TarHandler
 */
export function detectTarArchive(content: string): TarDetectionResult {
  // Check for tar magic bytes and patterns
  const hasUstar = content.includes("ustar");
  const hasPaxHeader = content.includes("PaxHeader");
  const hasGlobalHeader = content.includes("GlobalHeader");
  
  // Check for tar file entry patterns - look for the specific octal number patterns
  // that are characteristic of tar file headers
  const tarEntryPattern = /[a-zA-Z0-9_\-\.\/]+\x00[0-7]{8}[0-7]{8}[0-7]{8}[0-7]{12}[0-7]{12}[0-7]{8}[0-7]{8}[0-7]{1}/;
  const hasTarEntryPattern = tarEntryPattern.test(content);
  
  // Check for ustar magic at the end of tar headers
  const ustarMagicPattern = /ustar\x00[0-7]{2}/;
  const hasUstarMagic = ustarMagicPattern.test(content);
  
  // Check for GNU tar extended headers
  const gnuTarPattern = /GNU\s+tar/;
  const hasGnuTar = gnuTarPattern.test(content);
  
  // Check for binary null bytes which are common in tar archives
  const hasNullBytes = content.includes("\x00");
  
  // More balanced detection: require either strong tar indicators OR
  // a combination of tar patterns with null bytes (indicating binary content)
  const hasStrongTarIndicators = hasPaxHeader || hasGlobalHeader || (hasUstar && hasUstarMagic);
  const hasTarPatternsWithBinary = hasTarEntryPattern && hasNullBytes;
  const hasGnuTarWithBinary = hasGnuTar && hasNullBytes;
  
  // Additional detection: if we have ustar and null bytes, it's likely a tar archive
  const hasUstarWithBinary = hasUstar && hasNullBytes;
  
  const isTarArchive = hasStrongTarIndicators || hasTarPatternsWithBinary || hasGnuTarWithBinary || hasUstarWithBinary;
  

  return {
    isTarArchive,
    indicators: {
      hasUstar,
      hasPaxHeader,
      hasGlobalHeader,
      hasTarEntryPattern,
      hasUstarMagic,
      hasGnuTar,
      hasNullBytes
    }
  };
}
