import { 
  FormatDetector, 
  TextFormatDetector, 
  BinaryFormatDetector,
  DetectionOptions,
  DetectionResult 
} from "../detection/detection-interface.js";
import { ProgressOptions } from "../progress/index.js";

/**
 * Interface for compression handlers that can decompress data
 */
export interface CompressionHandler {
  /** Check if data is compressed with this format */
  isCompressed(data: Uint8Array): boolean;
  
  /** Decompress the data with optional progress reporting */
  decompress(data: Uint8Array, progressOptions?: ProgressOptions): Promise<CompressionResult>;
  
  /** Get the format name */
  getFormatName(): string;
  
  /** Get MIME type */
  getMimeType(): string;
  
  /** Get file extensions */
  getFileExtensions(): string[];
}

/**
 * Interface for content type detectors
 */
export interface ContentTypeHandler {
  /** Detect content type from text */
  detectContentType(content: string, projectId: string): ContentAnalysis;
  
  /** Get the format name */
  getFormatName(): string;
  
  /** Get MIME type */
  getMimeType(): string;
  
  /** Get file extensions */
  getFileExtensions(): string[];
}

/**
 * Interface for archive handlers that can extract files
 */
export interface ArchiveHandler {
  /** Check if content is an archive */
  isArchive(content: string): boolean;
  
  /** Extract files from archive */
  extractArchive(data: ArrayBuffer): Promise<ArchiveExtractionResult>;
  
  /** Get the format name */
  getFormatName(): string;
  
  /** Get MIME type */
  getMimeType(): string;
  
  /** Get file extensions */
  getFileExtensions(): string[];
}

/**
 * Result of compression decompression
 */
export interface CompressionResult {
  success: boolean;
  data?: string;
  binaryData?: Uint8Array;
  error?: string;
  originalSize: number;
  decompressedSize: number;
  processingTime: number;
}

/**
 * Result of archive extraction
 */
export interface ArchiveExtractionResult {
  success: boolean;
  xmlContent?: string;
  error?: string;
  extractedFiles: string[];
  xmlFile?: string;
  xmlFiles: ExtractedFile[];
  processingTime: number;
}

/**
 * Extracted file information
 */
export interface ExtractedFile {
  name: string;
  content: Uint8Array;
  size: number;
}

/**
 * Content analysis result
 */
export interface ContentAnalysis {
  type: string;
  confidence: "high" | "medium" | "low";
  indicators: Record<string, boolean>;
  details: {
    length: number;
    firstChars: string;
    lastChars: string;
  };
}

/**
 * Handler priority levels
 */
export enum HandlerPriority {
  LOW = 1,
  NORMAL = 2,
  HIGH = 3,
  CRITICAL = 4
}

/**
 * Handler registration information
 */
export interface HandlerRegistration {
  handler: CompressionHandler | ContentTypeHandler | ArchiveHandler | FormatDetector;
  priority: HandlerPriority;
  enabled: boolean;
  name: string;
  type: 'compression' | 'contentType' | 'archive' | 'detector';
}

/**
 * Registry for managing all data processing handlers
 */
export class HandlerRegistry {
  private handlers: Map<string, HandlerRegistration> = new Map();
  private compressionHandlers: Map<string, CompressionHandler> = new Map();
  private contentTypeHandlers: Map<string, ContentTypeHandler> = new Map();
  private archiveHandlers: Map<string, ArchiveHandler> = new Map();
  private detectors: Map<string, FormatDetector> = new Map();

  /**
   * Register a compression handler
   */
  registerCompressionHandler(
    handler: CompressionHandler, 
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    const name = handler.getFormatName();
    const registration: HandlerRegistration = {
      handler,
      priority,
      enabled,
      name,
      type: 'compression'
    };
    
    this.handlers.set(name, registration);
    this.compressionHandlers.set(name, handler);
  }

  /**
   * Register a content type handler
   */
  registerContentTypeHandler(
    handler: ContentTypeHandler, 
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    const name = handler.getFormatName();
    const registration: HandlerRegistration = {
      handler,
      priority,
      enabled,
      name,
      type: 'contentType'
    };
    
    this.handlers.set(name, registration);
    this.contentTypeHandlers.set(name, handler);
  }

  /**
   * Register an archive handler
   */
  registerArchiveHandler(
    handler: ArchiveHandler, 
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    const name = handler.getFormatName();
    const registration: HandlerRegistration = {
      handler,
      priority,
      enabled,
      name,
      type: 'archive'
    };
    
    this.handlers.set(name, registration);
    this.archiveHandlers.set(name, handler);
  }

  /**
   * Register a format detector
   */
  registerDetector(
    detector: FormatDetector, 
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    const name = detector.getFormatName();
    const registration: HandlerRegistration = {
      handler: detector,
      priority,
      enabled,
      name,
      type: 'detector'
    };
    
    this.handlers.set(name, registration);
    this.detectors.set(name, detector);
  }

  /**
   * Unregister a handler
   */
  unregisterHandler(name: string): boolean {
    const registration = this.handlers.get(name);
    if (!registration) return false;

    this.handlers.delete(name);
    
    switch (registration.type) {
      case 'compression':
        this.compressionHandlers.delete(name);
        break;
      case 'contentType':
        this.contentTypeHandlers.delete(name);
        break;
      case 'archive':
        this.archiveHandlers.delete(name);
        break;
      case 'detector':
        this.detectors.delete(name);
        break;
    }
    
    return true;
  }

  /**
   * Enable or disable a handler
   */
  setHandlerEnabled(name: string, enabled: boolean): boolean {
    const registration = this.handlers.get(name);
    if (!registration) return false;
    
    registration.enabled = enabled;
    return true;
  }

  /**
   * Get all enabled compression handlers sorted by priority
   */
  getEnabledCompressionHandlers(): CompressionHandler[] {
    return Array.from(this.compressionHandlers.entries())
      .filter(([name]) => {
        const registration = this.handlers.get(name);
        return registration?.enabled === true;
      })
      .map(([, handler]) => handler)
      .sort((a, b) => {
        const aReg = this.handlers.get(a.getFormatName());
        const bReg = this.handlers.get(b.getFormatName());
        return (bReg?.priority || 0) - (aReg?.priority || 0);
      });
  }

  /**
   * Get all enabled content type handlers sorted by priority
   */
  getEnabledContentTypeHandlers(): ContentTypeHandler[] {
    return Array.from(this.contentTypeHandlers.entries())
      .filter(([name]) => {
        const registration = this.handlers.get(name);
        return registration?.enabled === true;
      })
      .map(([, handler]) => handler)
      .sort((a, b) => {
        const aReg = this.handlers.get(a.getFormatName());
        const bReg = this.handlers.get(b.getFormatName());
        return (bReg?.priority || 0) - (aReg?.priority || 0);
      });
  }

  /**
   * Get all enabled archive handlers sorted by priority
   */
  getEnabledArchiveHandlers(): ArchiveHandler[] {
    return Array.from(this.archiveHandlers.entries())
      .filter(([name]) => {
        const registration = this.handlers.get(name);
        return registration?.enabled === true;
      })
      .map(([, handler]) => handler)
      .sort((a, b) => {
        const aReg = this.handlers.get(a.getFormatName());
        const bReg = this.handlers.get(b.getFormatName());
        return (bReg?.priority || 0) - (aReg?.priority || 0);
      });
  }

  /**
   * Get all enabled detectors sorted by priority
   */
  getEnabledDetectors(): FormatDetector[] {
    return Array.from(this.detectors.entries())
      .filter(([name]) => {
        const registration = this.handlers.get(name);
        return registration?.enabled === true;
      })
      .map(([, detector]) => detector)
      .sort((a, b) => {
        const aReg = this.handlers.get(a.getFormatName());
        const bReg = this.handlers.get(b.getFormatName());
        return (bReg?.priority || 0) - (aReg?.priority || 0);
      });
  }

  /**
   * Get a specific handler by name
   */
  getHandler<T extends CompressionHandler | ContentTypeHandler | ArchiveHandler | FormatDetector>(
    name: string, 
    type?: 'compression' | 'contentType' | 'archive' | 'detector'
  ): T | null {
    const registration = this.handlers.get(name);
    if (!registration) return null;
    
    if (type && registration.type !== type) return null;
    
    return registration.handler as T;
  }

  /**
   * Get all registered handlers
   */
  getAllHandlers(): HandlerRegistration[] {
    return Array.from(this.handlers.values());
  }

  /**
   * Clear all handlers
   */
  clear(): void {
    this.handlers.clear();
    this.compressionHandlers.clear();
    this.contentTypeHandlers.clear();
    this.archiveHandlers.clear();
    this.detectors.clear();
  }

  /**
   * Get handler statistics
   */
  getStats(): {
    total: number;
    byType: Record<string, number>;
    enabled: number;
    disabled: number;
  } {
    const handlers = Array.from(this.handlers.values());
    const byType: Record<string, number> = {
      compression: 0,
      contentType: 0,
      archive: 0,
      detector: 0
    };
    
    handlers.forEach(handler => {
      byType[handler.type] = (byType[handler.type] || 0) + 1;
    });
    
    return {
      total: handlers.length,
      byType,
      enabled: handlers.filter(h => h.enabled).length,
      disabled: handlers.filter(h => !h.enabled).length
    };
  }
}
