import { HandlerPriority } from "./handler-registry.js";

/**
 * Configuration options for the data loader
 */
export interface DataLoaderConfig {
  /** Enable/disable specific handlers by name */
  enabledHandlers?: {
    compression?: string[];
    contentType?: string[];
    archive?: string[];
    detector?: string[];
  };
  
  /** Disable specific handlers by name */
  disabledHandlers?: {
    compression?: string[];
    contentType?: string[];
    archive?: string[];
    detector?: string[];
  };
  
  /** Processing options */
  processing?: {
    /** Enable tar extraction */
    enableTarExtraction?: boolean;
    /** Force a specific content type */
    forceContentType?: string;
    /** Maximum file size to process (in bytes) */
    maxFileSize?: number;
    /** Timeout for processing operations (in milliseconds) */
    processingTimeout?: number;
    /** Enable detailed logging */
    enableLogging?: boolean;
  };
  
  /** Detection options */
  detection?: {
    /** Perform deep analysis (more accurate but slower) */
    deepAnalysis?: boolean;
    /** Maximum bytes to analyze for detection */
    maxBytes?: number;
    /** Minimum confidence level for detection */
    minConfidence?: "low" | "medium" | "high";
  };
  
  /** Custom handler priorities */
  handlerPriorities?: Record<string, HandlerPriority>;
  
  /** Custom handler configurations */
  handlerConfigs?: Record<string, Record<string, any>>;
}

/**
 * Default configuration
 */
export const DEFAULT_CONFIG: DataLoaderConfig = {
  processing: {
    enableTarExtraction: true,
    maxFileSize: 100 * 1024 * 1024, // 100MB
    processingTimeout: 60000, // 60 seconds
    enableLogging: false
  },
  detection: {
    deepAnalysis: false,
    maxBytes: 1024 * 1024, // 1MB
    minConfidence: "low"
  }
};

/**
 * Configuration manager for data loader
 */
export class ConfigurationManager {
  private config: DataLoaderConfig;

  constructor(config: DataLoaderConfig = {}) {
    this.config = this.mergeConfig(DEFAULT_CONFIG, config);
  }

  /**
   * Merge configuration objects deeply
   */
  private mergeConfig(target: any, source: any): any {
    const result = { ...target };
    
    for (const key in source) {
      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
        result[key] = this.mergeConfig(target[key] || {}, source[key]);
      } else {
        result[key] = source[key];
      }
    }
    
    return result;
  }

  /**
   * Update configuration
   */
  updateConfig(updates: Partial<DataLoaderConfig>): void {
    this.config = this.mergeConfig(this.config, updates);
  }

  /**
   * Get current configuration
   */
  getConfig(): DataLoaderConfig {
    return { ...this.config };
  }

  /**
   * Get a specific configuration value
   */
  get<K extends keyof DataLoaderConfig>(key: K): DataLoaderConfig[K] {
    return this.config[key];
  }

  /**
   * Get processing configuration
   */
  getProcessingConfig() {
    return this.config.processing || {};
  }

  /**
   * Get detection configuration
   */
  getDetectionConfig() {
    return this.config.detection || {};
  }

  /**
   * Check if a handler is enabled
   */
  isHandlerEnabled(handlerName: string, type: 'compression' | 'contentType' | 'archive' | 'detector'): boolean {
    const enabled = this.config.enabledHandlers?.[type];
    const disabled = this.config.disabledHandlers?.[type];
    
    // If explicitly disabled, return false
    if (disabled?.includes(handlerName)) {
      return false;
    }
    
    // If enabled list exists and doesn't include this handler, return false
    if (enabled && !enabled.includes(handlerName)) {
      return false;
    }
    
    // Default to enabled
    return true;
  }

  /**
   * Get handler priority
   */
  getHandlerPriority(handlerName: string): HandlerPriority {
    return this.config.handlerPriorities?.[handlerName] || HandlerPriority.NORMAL;
  }

  /**
   * Get handler configuration
   */
  getHandlerConfig(handlerName: string): Record<string, any> {
    return this.config.handlerConfigs?.[handlerName] || {};
  }

  /**
   * Validate configuration
   */
  validate(): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    
    // Validate file size
    const maxFileSize = this.config.processing?.maxFileSize;
    if (maxFileSize !== undefined && maxFileSize <= 0) {
      errors.push("maxFileSize must be positive");
    }
    
    // Validate timeout
    const timeout = this.config.processing?.processingTimeout;
    if (timeout !== undefined && timeout <= 0) {
      errors.push("processingTimeout must be positive");
    }
    
    // Validate max bytes
    const maxBytes = this.config.detection?.maxBytes;
    if (maxBytes !== undefined && maxBytes <= 0) {
      errors.push("maxBytes must be positive");
    }
    
    return {
      valid: errors.length === 0,
      errors
    };
  }

  /**
   * Reset to default configuration
   */
  reset(): void {
    this.config = { ...DEFAULT_CONFIG };
  }
}
