import {
  HandlerRegistry,
  HandlerPriority,
} from '../configuration/handler-registry.js';
import {
  ConfigurationManager,
  DataLoaderConfig,
} from '../configuration/configuration.js';
import { FormatProcessor } from './format-processor.js';
export { FormatProcessingResult, FormatProcessingOptions } from './format-processing-types.js';
import {
  GzipCompressionAdapter,
  XzCompressionAdapter,
} from '../adapters/compression-adapters.js';
import { ContentTypeDetectorAdapter } from '../adapters/content-type-adapters.js';
import { TarArchiveAdapter } from '../adapters/archive-adapters.js';

/**
 * Factory for creating data processors with custom configurations
 */
export class ProcessorFactory {
  private registry: HandlerRegistry;
  private configManager: ConfigurationManager;

  constructor(config?: DataLoaderConfig) {
    this.registry = new HandlerRegistry();
    this.configManager = new ConfigurationManager(config);
  }

  /**
   * Create a new processor instance with current configuration
   */
  createProcessor(): FormatProcessor {
    return new FormatProcessor(this.registry, this.configManager);
  }

  /**
   * Get the handler registry
   */
  getRegistry(): HandlerRegistry {
    return this.registry;
  }

  /**
   * Get the configuration manager
   */
  getConfigManager(): ConfigurationManager {
    return this.configManager;
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<DataLoaderConfig>): void {
    this.configManager.updateConfig(config);
  }

  /**
   * Register a compression handler
   */
  registerCompressionHandler(
    handler: any,
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    this.registry.registerCompressionHandler(handler, priority, enabled);
  }

  /**
   * Register a content type handler
   */
  registerContentTypeHandler(
    handler: any,
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    this.registry.registerContentTypeHandler(handler, priority, enabled);
  }

  /**
   * Register an archive handler
   */
  registerArchiveHandler(
    handler: any,
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    this.registry.registerArchiveHandler(handler, priority, enabled);
  }

  /**
   * Register a format detector
   */
  registerDetector(
    detector: any,
    priority: HandlerPriority = HandlerPriority.NORMAL,
    enabled: boolean = true
  ): void {
    this.registry.registerDetector(detector, priority, enabled);
  }

  /**
   * Unregister a handler
   */
  unregisterHandler(name: string): boolean {
    return this.registry.unregisterHandler(name);
  }

  /**
   * Enable or disable a handler
   */
  setHandlerEnabled(name: string, enabled: boolean): boolean {
    return this.registry.setHandlerEnabled(name, enabled);
  }

  /**
   * Get processor statistics
   */
  getStats() {
    return {
      handlers: this.registry.getStats(),
      config: this.configManager.getConfig(),
    };
  }
}

/**
 * Create a default processor factory with built-in handlers
 */
export function createDefaultProcessorFactory(
  config?: DataLoaderConfig
): ProcessorFactory {
  const factory = new ProcessorFactory(config);

  // Register built-in compression handlers
  factory.registerCompressionHandler(
    new GzipCompressionAdapter(),
    HandlerPriority.HIGH,
    true
  );

  factory.registerCompressionHandler(
    new XzCompressionAdapter(),
    HandlerPriority.HIGH,
    true
  );

  // Register built-in content type handler
  factory.registerContentTypeHandler(
    new ContentTypeDetectorAdapter(),
    HandlerPriority.CRITICAL,
    true
  );

  // Register built-in archive handler
  factory.registerArchiveHandler(
    new TarArchiveAdapter(),
    HandlerPriority.HIGH,
    true
  );

  return factory;
}

/**
 * Create a processor factory with only specific handlers
 */
export function createCustomProcessorFactory(
  handlers: {
    compression?: any[];
    contentType?: any[];
    archive?: any[];
    detector?: any[];
  },
  config?: DataLoaderConfig
): ProcessorFactory {
  const factory = new ProcessorFactory(config);

  // Register provided handlers
  handlers.compression?.forEach((handler) => {
    factory.registerCompressionHandler(handler);
  });

  handlers.contentType?.forEach((handler) => {
    factory.registerContentTypeHandler(handler);
  });

  handlers.archive?.forEach((handler) => {
    factory.registerArchiveHandler(handler);
  });

  handlers.detector?.forEach((detector) => {
    factory.registerDetector(detector);
  });

  return factory;
}
