import { ContentTypeHandler, ContentAnalysis } from "../configuration/handler-registry.js";
import { ContentTypeDetector as OriginalContentTypeDetector, ContentAnalysis as OriginalContentAnalysis } from "../handlers/content-type/content-type-detector.js";

/**
 * Adapter for ContentTypeDetector to implement ContentTypeHandler interface
 */
export class ContentTypeDetectorAdapter implements ContentTypeHandler {
  private handler: OriginalContentTypeDetector;

  constructor() {
    this.handler = new OriginalContentTypeDetector();
  }

  detectContentType(content: string, projectId: string): ContentAnalysis {
    const analysis = this.handler.detectContentType(content, projectId);
    
    return {
      type: analysis.type,
      confidence: analysis.confidence,
      indicators: analysis.indicators,
      details: analysis.details
    };
  }

  getFormatName(): string {
    return this.handler.getFormatName();
  }

  getMimeType(): string {
    return this.handler.getMimeType();
  }

  getFileExtensions(): string[] {
    return this.handler.getFileExtensions();
  }
}
