
import { detectTarArchive } from "../archive/tar-detection.js";
import { DetectionResult, DetectionOptions } from "../../detection/detection-interface.js";
import { BaseTextDetector, DetectionUtils } from "../../detection/unified-detector.js";

export type ContentType = "xml" | "tsv" | "tar" | "json" | "unknown";

export interface ContentAnalysis {
  type: ContentType;
  confidence: "high" | "medium" | "low";
  indicators: {
    hasTarHeader: boolean;
    hasXMLContent: boolean;
    hasTabs: boolean;
    hasTSVStructure: boolean;
    isOMWPackage: boolean;
    hasOMWIndicators: boolean;
    hasBinaryTarContent: boolean;
    // Custom indicators for extensibility
    [key: string]: boolean;
  };
  details: {
    length: number;
    firstChars: string;
    lastChars: string;
  };
}

/**
 * Detects the content type by examining decompressed file content
 */
export class ContentTypeDetector extends BaseTextDetector {

  // FormatDetector interface implementation
  getFormatName(): string {
    return "content-type";
  }

  getMimeType(): string {
    return "text/plain";
  }

  getFileExtensions(): string[] {
    return [".xml", ".tsv", ".txt"];
  }

  analyzeText(content: string, options?: DetectionOptions): DetectionResult {
    const trimmedContent = content.trim();
    
    if (trimmedContent.length === 0) {
      return {
        isDetected: false,
        confidence: "low",
        indicators: {},
        metadata: { isEmpty: true }
      };
    }

    // Use sampling for performance on large content
    const sampleSize = Math.min(trimmedContent.length, 1024 * 1024); // 1MB sample
    const contentSample = trimmedContent.substring(0, sampleSize);

    // Check for XML content
    const hasXMLContent = contentSample.includes("<?xml") || contentSample.includes("<");
    
    // Check for TSV content
    const hasTSVContent = contentSample.includes("\t") && 
                         !contentSample.includes("<?xml") &&
                         !contentSample.includes("<");
    
    // Check for tar content
    const tarDetection = detectTarArchive(contentSample);
    
    const indicators = {
      hasXMLContent,
      hasTSVContent,
      hasTarContent: tarDetection.isTarArchive,
      hasTextContent: !hasXMLContent && !hasTSVContent && !tarDetection.isTarArchive,
      hasBinaryContent: contentSample.length > 1000 && 
                       (contentSample.includes("\x00") || 
                        contentSample.includes("\x1f") || 
                        contentSample.includes("\x7f"))
    };

    const weights = {
      hasXMLContent: 3,
      hasTSVContent: 3,
      hasTarContent: 3,
      hasTextContent: 1,
      hasBinaryContent: 2
    };

    const confidence = DetectionUtils.calculateConfidence(indicators, weights);
    const isDetected = hasXMLContent || hasTSVContent || tarDetection.isTarArchive;

    return {
      isDetected,
      confidence,
      indicators,
      metadata: {
        ...DetectionUtils.extractMetadata(indicators),
        contentLength: trimmedContent.length,
        firstChars: contentSample.substring(0, 200),
        lastChars: contentSample.substring(Math.max(0, contentSample.length - 200))
      }
    };
  }

  /**
   * Detect the content type by examining the decompressed file content
   */
  detectContentType(
    content: string,
    projectIdWithVersion: string
  ): ContentAnalysis {
    const trimmedContent = content.trim();

    if (trimmedContent.length === 0) {
      return this.createAnalysis("unknown", "low", projectIdWithVersion, trimmedContent);
    }

    // For large content, use sampling to improve performance
    const sampleSize = Math.min(trimmedContent.length, 1024 * 1024); // 1MB sample
    const contentSample = trimmedContent.substring(0, sampleSize);

    // Check for tar archive indicators (after decompression) - use sample for performance
    const tarDetection = detectTarArchive(contentSample);
    const hasTarHeader = tarDetection.isTarArchive;

    // Check for XML content - use sample for performance
    const hasXMLContent =
      contentSample.includes("<?xml") ||
      contentSample.includes("<");

    // Check for TSV content (tab-separated values) - use sample for performance
    const hasTSVContent = 
      contentSample.includes("\t") && 
      !contentSample.includes("<?xml") &&
      !contentSample.includes("<");

    // Check for binary tar content - use sample for performance
    const hasBinaryTarContent = 
      contentSample.length > 1000 && 
      (contentSample.includes("\x00") || // null bytes
       contentSample.includes("\x1f") || // control characters
       contentSample.includes("\x7f"));  // delete character

    // Check for TSV content - use sample for performance
    const hasTabs = contentSample.includes("\t");
    const hasTSVStructure = hasTabs && contentSample.includes("\n");

    // Determine content type with confidence
    let type: ContentType;
    let confidence: "high" | "medium" | "low";

    // If we detect tar indicators, prioritize tar detection over other types
    // Check for tar archive content
    if (hasTarHeader || hasBinaryTarContent) {
      type = "tar";
      confidence = hasTarHeader ? "high" : "medium";
    }
    // Check for TSV content (tab-separated values)
    else if (hasTSVContent && !hasTarHeader) {
      type = "tsv";
      confidence = "high";
    }
    // Check for XML content (only if no tar indicators)
    else if (hasXMLContent && !hasTarHeader) {
      type = "xml";
      confidence = "high";
    }
    // Fallback to XML if we have some XML-like content
    else if (hasXMLContent) {
      type = "xml";
      confidence = "low";
    }
    else {
      type = "unknown";
      confidence = "low";
    }


    return this.createAnalysis(type, confidence, projectIdWithVersion, trimmedContent);
  }

  private createAnalysis(
    type: ContentType,
    confidence: "high" | "medium" | "low",
    projectId: string,
    content: string
  ): ContentAnalysis {
    // Use sampling for performance on large content
    const sampleSize = Math.min(content.length, 1024 * 1024); // 1MB sample
    const contentSample = content.substring(0, sampleSize);
    
    const tarDetection = detectTarArchive(contentSample);
    
    return {
      type,
      confidence,
      indicators: {
        hasTarHeader: tarDetection.isTarArchive,
        hasXMLContent: contentSample.includes("<?xml") || contentSample.includes("<LexicalResource") || contentSample.includes("<lexicon"),
        hasTabs: contentSample.includes("\t"),
        hasTSVStructure: contentSample.includes("\t") && contentSample.includes("\n"),
        isOMWPackage: projectId.startsWith("omw-"),
        hasOMWIndicators: contentSample.includes("omw-") || contentSample.includes("wolf") || contentSample.includes("french") || contentSample.includes("thai"),
        hasBinaryTarContent: contentSample.length > 1000 && (contentSample.includes("\x00") || contentSample.includes("\x1f") || contentSample.includes("\x7f"))
      },
      details: {
        length: content.length,
        firstChars: content.substring(0, 200),
        lastChars: content.substring(Math.max(0, content.length - 200))
      }
    };
  }
}
