import { CompressionHandler, CompressionResult } from "../configuration/handler-registry.js";
import { GzipHandler as OriginalGzipHandler, GzipDecompressionResult } from "../handlers/compression/gzip-handler.js";
import { XzHandler as OriginalXzHandler, XzDecompressionResult } from "../handlers/compression/xz-handler.js";

/**
 * Adapter for GzipHandler to implement CompressionHandler interface
 */
export class GzipCompressionAdapter implements CompressionHandler {
  private handler: OriginalGzipHandler;

  constructor() {
    this.handler = new OriginalGzipHandler();
  }

  isCompressed(data: Uint8Array): boolean {
    return this.handler.isGzipCompressed(data);
  }

  async decompress(data: Uint8Array): Promise<CompressionResult> {
    const result = await this.handler.decompress(data);
    
    return {
      success: result.success,
      data: result.data,
      binaryData: result.binaryData,
      error: result.error,
      originalSize: result.originalSize,
      decompressedSize: result.decompressedSize,
      processingTime: result.processingTime
    };
  }

  getFormatName(): string {
    return this.handler.getFormatName();
  }

  getMimeType(): string {
    return this.handler.getMimeType();
  }

  getFileExtensions(): string[] {
    return this.handler.getFileExtensions();
  }
}

